27|type DispatchConfig struct {
28|	Port         int           `json:"port"`
29|	Timeout      time.Duration `json:"timeout"`
30|	MaxRetries   int           `json:"max_retries"`
31|	MaxQueueSize int           `json:"max_queue_size"`
32|}
33|
34|type TaskRequest struct {
35|	ID        string          `json:"id"`
36|	SessionID string          `json:"session_id"`
37|	Payload   json.RawMessage `json:"payload"`
38|}
39|
40|type TaskResponse struct {
41|	ID        string `json:"id"`
42|	Status    string `json:"status"`
43|	ResultHash string `json:"result_hash"`
44|	DurationMs int64  `json:"duration_ms"`
45|}
46|
47|type DispatcherService struct {
48|	cfg     DispatchConfig
49|	mu      sync.Mutex
50|	server  *http.Server
51|	running bool
52|	tasks   map[string]TaskResponse
53|}
54|
55|func NewDispatcherService(cfg DispatchConfig) *DispatcherService {
56|	return &DispatcherService{
57|		cfg:   cfg,
58|		tasks: make(map[string]TaskResponse),
59|	}
60|}
61|
62|func (s *DispatcherService) HashPayload(b []byte) string {
63|	h := sha256.Sum256(b)
64|	return hex.EncodeToString(h[:16])
65|}
66|
67|func (s *DispatcherService) IsRunning() bool {
68|	s.mu.Lock()
69|	defer s.mu.Unlock()
70|	return s.running
71|}
72|
73|func (s *DispatcherService) ProcessTask(ctx context.Context, req TaskRequest) (TaskResponse, error) {
74|	start := time.Now()
75|	if req.ID == "" {
76|		return TaskResponse{}, errors.New("task ID cannot be empty")
77|	}
78|	hash := s.HashPayload(req.Payload)
79|	
80|	// Complex multi-step processing simulation (oversized method body to test folding)
81|	var intermediateState map[string]interface{}
82|	if err := json.Unmarshal(req.Payload, &intermediateState); err != nil {
83|		return TaskResponse{}, fmt.Errorf("failed unmarshaling payload: %w", err)
84|	}
85|
86|	for k, v := range intermediateState {
87|		// Log processing steps
88|		if strVal, ok := v.(string); ok && len(strVal) > 50 {
89|			intermediateState[k] = strVal[:50] + "..."
90|		}
91|	}
92|
93|	s.mu.Lock()
94|	resp := TaskResponse{
95|		ID:         req.ID,
96|		Status:     "success",
97|		ResultHash: hash,
98|		DurationMs: time.Since(start).Milliseconds(),
99|	}
100|	s.tasks[req.ID] = resp
101|	s.mu.Unlock()
102|
103|	return resp, nil
104|}
